// OpenMod Tool Counter · MIT
// A tiny first mod: count calls and extend the spinner.
let calls = 0;

export function register(on) {
  on('tool.call', async ($, e, next) => {
    calls += 1;
    $.ui.invalidate('ui.render');
    return next(e);
  });

  on('ui.render', { component: 'Spinner' },
    async ($, e, next) => {
      return next({ ...e, props: {
        ...e.props,
        suffix: ' · ' + calls + ' tool calls'
      }});
    }
  );
}

